"""
Certificate
"""
from builtins import object
from taf.ul.trs_e2e_fw.lib.oam.btssm.btssm_factory import BtssmFactory
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()


class Certificate(object):
    """
    Certificate
    """
    def __init__(self):
        self.oam_tool = BtssmFactory().get_instance().oam_tool

    def certificate_configure(self, **kwargs):
        """
        Function to configure certificate
        """
        operation = kwargs.get("operation")
        if operation.lower() == "add_bts_ta_certificate":
            self._add_bts_ta_certificate(**kwargs)
        elif operation.lower() == "add_certificate":
            self._add_certificate(**kwargs)
        elif operation.lower() == "delete_bts_ta_certificate":
            self._delete_bts_ta_certificate(**kwargs)
        elif operation.lower() == "fetch_certificates":
            self.fetch_certificates(**kwargs)
        elif operation.lower() == "restore_vendor_certificates":
            self.restore_vendor_certificates(**kwargs)
        elif operation.lower() == "Cmp_init_request":
            self.cmp_init_request(**kwargs)
        elif operation.lower() == "cmp_key_update_request":
            self.cmp_key_update_request(**kwargs)
        elif operation.lower() == "display_certificates":
            self.display_certificates(**kwargs)
        else:
            raise Exception("{}, Operation Not Supported.".format(operation))

    def _add_bts_ta_certificate(self, **kwargs):
        ta_cert_file = kwargs.get("ta_cert_file")
        ta_pkcs12_password = kwargs.get("ta_pkcs12_password")
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["ta_cert_file", "ta_pkcs12_password", "timeout"]}
        self.oam_tool.add_bts_ta_certificate(ta_cert_file=ta_cert_file,
                                             ta_pkcs12_password=ta_pkcs12_password,
                                             timeout=timeout, **kwargs)

    def _add_certificate(self, **kwargs):
        certificate_file = kwargs.get("certificate_file", None)
        certificate_password = kwargs.get("certificate_password", None)
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["certificate_file", "certificate_password", "timeout"]}
        self.oam_tool.add_certificate(certificate_file=certificate_file,
                                      certificate_password=certificate_password,
                                      timeout=timeout, **kwargs)

    def _delete_bts_ta_certificate(self, **kwargs):
        issuers = kwargs.get("issuers")
        serial_nos = kwargs.get("serial_nos")
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["issuers", "serial_nos", "timeout"]}
        self.oam_tool._delete_bts_ta_certificate(issuers=issuers, serial_nos=serial_nos,
                                                 timeout=timeout, **kwargs)

    def fetch_certificates(self, **kwargs):
        """
        Function to fetch certificate
        """
        output_directory = kwargs.get("output_directory")
        output_format = kwargs.get("output_format", None)
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["output_directory", "output_format", "timeout"]}
        self.oam_tool.fetch_certificates(output_directory=output_directory,
                                         output_format=output_format,
                                         timeout=timeout, **kwargs)

    def restore_vendor_certificates(self, **kwargs):
        """
        Function to restore vendor certificates
        """
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout"]}
        self.oam_tool.restore_vendor_certificates(timeout=timeout, **kwargs)

    def cmp_init_request(self, **kwargs):
        """
        Function call cmp init request
        """
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout"]}
        self.oam_tool.cmp_init_request(timeout=timeout, **kwargs)

    def cmp_key_update_request(self, **kwargs):
        """
        Function to call cmp key update request
        """
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout"]}
        self.oam_tool.cmp_key_update_request(timeout=timeout, **kwargs)

    def display_certificates(self, **kwargs):
        """
        Function to display certificates
        """
        cert_type = kwargs.get("cert_type", "all")
        timeout = kwargs.get("timeout", "5min")
        kwargs = {key: value for key, value in list(kwargs.items()) if
                  key not in ["timeout", "cert_type"]}
        self.oam_tool.display_certificates(cert_type=cert_type, timeout=timeout, **kwargs)
